{
  "items": [
    {
      "title": "German Federal Statistical Office (Destatis) – GENESIS-Online Database",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/",
      "justification": "Germany's official statistical database provides comprehensive economic indicators covering the 2010s and 2020s. Includes GDP, economic growth, inflation, consumer prices, employment, unemployment, wages, industrial production, household income, government finances, and foreign trade. Offers monthly, quarterly, and annual observations, making it particularly useful for analyzing Germany's economic performance before, during, and after the COVID-19 pandemic."
    },
    {
      "title": "Deutsche Bundesbank – Long Time Series on Economic Development in Germany",
      "url_or_doi": "https://www.bundesbank.de/en/statistics/sets-of-indicators/long-time-series",
      "justification": "Official historical economic dataset published by Germany's central bank, covering economic development from 1948 through the 2010s and 2020s. Includes monetary and banking statistics, interest rates, capital markets, labor market indicators, wages, consumer prices, public finances, international trade, and exchange rates. Particularly valuable for studying long-term structural changes and comparing economic conditions across decades. Downloadable spreadsheet data are available."
    },
    {
      "title": "World Bank – World Development Indicators: Germany",
      "url_or_doi": "https://data.worldbank.org/country/germany",
      "justification": "Comprehensive collection of internationally comparable economic and development indicators for Germany. Covers GDP, GDP per capita, annual economic growth, inflation, unemployment, government debt, foreign direct investment, trade, productivity-related measures, and socioeconomic conditions. Historical annual data encompass the 2010s and 2020s. Particularly useful for comparing Germany's economic performance with other European countries and major global economies. Data can be downloaded in CSV and Excel formats."
    },
    {
      "title": "Eurostat – European Statistical Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/data/database",
      "justification": "Official statistical database of the European Union, containing harmonized economic indicators for Germany and other European countries. Includes quarterly GDP, inflation, unemployment, employment, industrial production, household consumption, investment, government expenditure, public debt, and international trade. Provides extensive coverage of the 2010s and 2020s, with monthly, quarterly, and annual observations. Especially suitable for analyzing Germany's economic performance relative to the EU and euro area."
    },
    {
      "title": "International Monetary Fund – World Economic Outlook Database",
      "url_or_doi": "https://www.imf.org/external/datamapper/datasets/WEO",
      "justification": "International macroeconomic database containing historical economic indicators and projections for Germany. Covers real GDP growth, nominal GDP, GDP per capita, inflation, unemployment, current account balances, government deficits, and public debt. The October 2026 edition provides historical annual series covering both the 2010s and 2020s, along with projections. Useful for studying Germany's economic cycles, fiscal sustainability, inflationary pressures, and medium-term economic outlook."
    },
    {
      "title": "Deutsche Bundesbank – Macroeconomic Time Series and Real-Time Data",
      "url_or_doi": "https://www.bundesbank.de/de/statistiken/zeitreihen-und-echtzeitdaten",
      "justification": "Official Bundesbank statistical resource providing detailed macroeconomic time series and historical economic data vintages. Includes monetary aggregates, banking activity, interest rates, financial markets, domestic economic activity, external sector statistics, and other indicators. Particularly useful for analyzing economic fluctuations during the 2010–2026 period, monetary conditions, and the effects of major shocks. Data are available in machine-readable formats, including CSV and SDMX."
    },
    {
      "title": "Destatis – Short-Term Economic Indicators",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/short-term-indicators.html",
      "justification": "Official German statistical resource covering high-frequency economic indicators. Includes measures of industrial activity, economic output, prices, labor market developments, and other indicators of short-term economic conditions. Relevant for tracking Germany's business cycle throughout the 2010s and 2020s, particularly the COVID-19 economic disruption, subsequent recovery, and inflationary developments. The underlying statistical series are accessible through Destatis GENESIS-Online."
    },
    {
      "title": "OECD – Economic Outlook Statistical Annex",
      "url_or_doi": "https://www.oecd.org/en/topics/sub-issues/economic-outlook/oecd-economic-outlook-statistical-annex.html",
      "justification": "OECD statistical collection containing historical macroeconomic indicators and economic projections for Germany and other OECD economies. Covers real and nominal GDP, consumer price inflation, unemployment, government fiscal balances, interest rates, exchange rates, and international trade. Suitable for comparing Germany's economic development during the 2010s and 2020s against other advanced economies and studying changes in growth, inflation, and public finances."
    },
    {
      "title": "Deutsche Bundesbank – Research Data and Economic Statistics",
      "url_or_doi": "https://www.bundesbank.de/en/bundesbank/research/rdsc/research-data",
      "justification": "Official research data catalog maintained by the Deutsche Bundesbank, providing access to detailed German financial and economic datasets. Includes banking statistics, credit information, macroeconomic indicators, financial sector statistics, and selected business-related data. Particularly valuable for academic research investigating the relationships between financial conditions, lending, banking activity, and Germany's economic performance during the 2010s and 2020s. Access requirements vary by dataset."
    },
    {
      "title": "Eurostat – Quarterly National Accounts: GDP and Main Components",
      "url_or_doi": "https://ec.europa.eu/eurostat/data/database",
      "justification": "Eurostat's quarterly national accounts dataset, identifiable by the dataset code 'namq_10_gdp', provides Germany's quarterly GDP and expenditure components. Includes household consumption, government consumption, gross capital formation, exports, and imports, with nominal and volume-based measures. Particularly useful for studying quarterly economic growth throughout 2010–2026, including Germany's pandemic recession, recovery, and subsequent economic stagnation. Germany can be selected using the geographic code DE."
    },
    {
      "title": "Eurostat – Harmonised Index of Consumer Prices (HICP)",
      "url_or_doi": "https://ec.europa.eu/eurostat/data/database",
      "justification": "Eurostat's harmonized consumer price statistics provide comparable inflation data for Germany and other European countries. Includes monthly consumer price indices, annual inflation rates, and price developments across major consumption categories. Particularly useful for studying Germany's inflation trends during the 2010s, the sharp increase in prices during 2021–2023, and subsequent developments. The harmonized methodology enables comparisons with other euro-area economies."
    },
    {
      "title": "Eurostat – Labor Market and Unemployment Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/data/database",
      "justification": "Official harmonized European labor market statistics covering Germany throughout the 2010s and 2020s. Includes unemployment rates, employment levels, labor force participation, youth unemployment, and demographic breakdowns. Monthly and quarterly data support analysis of Germany's labor market resilience, demographic pressures, pandemic-related disruptions, and employment trends. Particularly useful for comparisons with other EU member states."
    },
    {
      "title": "IMF – International Macroeconomic and Financial Statistics",
      "url_or_doi": "https://data.imf.org/en",
      "justification": "The IMF Data Portal provides access to internationally standardized macroeconomic and financial datasets covering Germany. Relevant collections include national economic accounts, balance of payments, international investment positions, government finance statistics, consumer prices, and international financial statistics. Historical observations spanning the 2010s and 2020s are useful for examining Germany's external balances, financial conditions, fiscal performance, and overall macroeconomic stability."
    },
    {
      "title": "European Central Bank – Key ECB Interest Rates",
      "url_or_doi": "https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.de.html",
      "justification": "Official historical dataset documenting European Central Bank policy interest rates, including the deposit facility, main refinancing operations, and marginal lending facility rates. Although these rates apply to the euro area rather than Germany alone, they are important indicators of the monetary policy environment affecting the German economy. Historical observations cover the 2010s and 2020s and are useful for analyzing monetary accommodation, the negative-interest-rate period, and tightening in response to inflation."
    },
    {
      "title": "Destatis – Basic Economic Indicators for Germany",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Countries-Regions/International-Statistics/Country/Europe/DE.html",
      "justification": "Official German statistical overview compiling important economic and socioeconomic indicators from international statistical sources. Includes economic growth, inflation, employment-related measures, and other indicators relevant to Germany's economic conditions. Useful as an accessible starting point for identifying key variables and comparing Germany with other countries. Best suited for summary statistics rather than detailed historical time-series analysis."
    },
    {
      "title": "OECD – Economic Outlook and Historical Macroeconomic Indicators",
      "url_or_doi": "https://www.oecd.org/en/topics/sub-issues/economic-outlook/oecd-economic-outlook-statistical-annex.html",
      "justification": "The OECD Economic Outlook statistical data provide a structured foundation for studying Germany's macroeconomic performance across the 2010s and 2020s. Particularly relevant variables include domestic demand, economic growth, inflation, unemployment, fiscal balances, and international trade. The combination of historical observations and projections supports analysis of Germany's economic slowdown, recovery patterns, and changing medium-term growth prospects."
    }
  ]
}
